// Evaluador de juguete: Effect, Action y Resource con comodín *.
const coincide = (patron, valor) =>
  new RegExp('^' + patron.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*') + '$').test(valor);
const lista = (x) => (Array.isArray(x) ? x : [x]);

function evaluar(politicas, accion, recurso) {
  let permitido = false;
  for (const pol of politicas) {
    for (const st of pol.Statement) {
      const aplica =
        lista(st.Action).some((a) => coincide(a, accion)) &&
        lista(st.Resource).some((r) => coincide(r, recurso));
      if (!aplica) continue;
      if (st.Effect === 'Deny') return 'DENEGADO (deny explícito: ' + (st.Sid || '?') + ')';
      if (st.Effect === 'Allow') permitido = true;
    }
  }
  return permitido ? 'PERMITIDO' : 'DENEGADO (implícito: nadie lo permitió)';
}

