const coincide = (p, v) => new RegExp('^' + p.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*') + '$').test(v);
const lista = (x) => (Array.isArray(x) ? x : [x]);
function evaluar(pols, accion, recurso) {
  let ok = false;
  for (const p of pols) for (const st of p.Statement) {
    if (!lista(st.Action).some((a) => coincide(a, accion)) || !lista(st.Resource).some((r) => coincide(r, recurso))) continue;
