const enc = new TextEncoder();
const b64 = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/=/g, '');
const SECRETO = 'secreto-de-juguete-del-servicio';
async function firmar(texto) {
  const k = await crypto.subtle.importKey('raw', enc.encode(SECRETO), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return b64(await crypto.subtle.sign('HMAC', k, enc.encode(texto)));
}
async function emitir(rol, ahora, duracionS) {
  const cuerpo = JSON.stringify({ rol, vence: ahora + duracionS });
  return btoa(cuerpo) + '.' + (await firmar(cuerpo));
}
async function usar(cred, ahora) {
  const [c, sig] = cred.split('.');
  const cuerpo = atob(c);
  if ((await firmar(cuerpo)) !== sig) return 'rechazada: firma falsa';
  const { rol, vence } = JSON.parse(cuerpo);
  return ahora >= vence ? 'rechazada: vencida hace ' + (ahora - vence) + ' s' : 'aceptada como ' + rol;
}
